def compute(vars):
    exports = vars["v1"]
    imports = vars["v2"]
    trade_volume = exports + imports

    return {
        "value": round(trade_volume, 2),
        "trace": {
            "exports": exports,
            "imports": imports,
            "trade_volume": trade_volume,
            "output_meta": {
                "currency": "美元",
                "scale": "百万",
                "unit": "金额"
            }
        }
    }
